const { Chessground } = await import('./dist/chessground.js');

const gc = () => {
  globalThis.gc();
  globalThis.gc();
};

// --- 1. redraw: old board (with listeners) must be collectible
const wrap = document.createElement('div');
document.body.appendChild(wrap);
let cg = Chessground(wrap, {});
const board1 = cg.state.dom.elements.board;
const boardRef = new WeakRef(board1);
cg.redrawAll(); // detaches board1; its listeners + closures were attached to it
delete cg.state; // drop api-level handle; board1 only lived in the old state.dom
gc();
